  afterEach(() => {
    db.close();
  });

  /**
   * @caso CT-API-010
   * @nivel api
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF03.2
   * @objetivo Listar especialidades para qualquer usuário autenticado
   * @resultadoEsperado Status 200 com array de especialidades cadastradas
   */
